// Runs on ALL rows the trigger emits (1 normally; 2+ if multiple forms land
// in one poll window or via Fetch Test Event). Process EVERY item.
const META = new Set([
  'Timestamp', 'Email Address', 'What is your name?',
  'What date, day and time do you need the food/service?',
  'Contact number or mobile (for confirmation & follow-up)',
  'What type of event are you planning?', 'Estimated number of guests attending:',
  'Service Method ', 'Service Method', 'Delivery location ', 'Delivery location',
  '"On which social media platform was the advertisement seen?"',
  'row_number', 'Invoice ID', 'Sync Status',
]);
// Robust metadata test: known META columns, the social-media
// question (curly OR straight quotes), and the policy/terms blob.
const isMeta = (h) => {
  if (META.has(h)) return true;
  const t = String(h).toLowerCase().trim();
  if (t.includes('social media platform')) return true;
  if (t.includes('order, payment') || t.startsWith('bagnetchon order')) return true;
  if (t.startsWith('delivery location')) return true;
  return false;
};


return $input.all().map((entry) => {
  const row = entry.json;
  const errors = [];

  const email = String(row['Email Address'] ?? '').trim();
  if (!email) errors.push('email is missing');
  else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errors.push('email format looks wrong');

  const name = String(row['What is your name?'] ?? '').trim();
  if (!name) errors.push('name is missing');

  const fulfillmentDate = String(row['What date, day and time do you need the food/service?'] ?? '').trim();
  if (!fulfillmentDate) errors.push('fulfillment date is missing');

  const serviceMethod = String(row['Service Method '] ?? row['Service Method'] ?? '').trim();
  if (!serviceMethod) errors.push('service method is missing');

  if (serviceMethod.toLowerCase().includes('delivery')) {
    const deliveryLocationKey = Object.keys(row).find((k) => String(k).toLowerCase().trim().startsWith('delivery location'));
  const deliveryLocation = deliveryLocationKey ? String(row[deliveryLocationKey] ?? '').trim() : '';
    if (!deliveryLocation) errors.push('delivery location is required for Delivery orders');
  }

  let hasSelection = false;
  for (const [k, v] of Object.entries(row)) {
    if (isMeta(k)) continue;

    if (v && String(v).trim()) { hasSelection = true; break; }
  }
  if (!hasSelection) errors.push('no menu items selected');

  return { json: { ok: errors.length === 0, row, errors } };
});

const crypto = require('crypto');

const META = new Set([
  'Timestamp', 'Email Address', 'What is your name?',
  'What date, day and time do you need the food/service?',
  'Contact number or mobile (for confirmation & follow-up)',
  'What type of event are you planning?', 'Estimated number of guests attending:',
  'Service Method ', 'Service Method', 'Delivery location ', 'Delivery location',
  '"On which social media platform was the advertisement seen?"',
  'row_number', 'Invoice ID', 'Sync Status',
]);
// Robust metadata test: known META columns, the social-media
// question (curly OR straight quotes), and the policy/terms blob.
const isMeta = (h) => {
  if (META.has(h)) return true;
  const t = String(h).toLowerCase().trim();
  if (t.includes('social media platform')) return true;
  if (t.includes('order, payment') || t.startsWith('bagnetchon order')) return true;
  if (t.startsWith('delivery location')) return true;
  return false;
};


return $input.all().map((entry) => {
  const row = entry.json.row;

  const email = String(row['Email Address'] ?? '').trim().toLowerCase();
  const timestamp = String(row['Timestamp'] ?? '').trim();

  const idHash = crypto.createHash('sha256').update(timestamp + '|' + email).digest('hex').slice(0, 16);

  const selected_items = [];
  for (const [k, v] of Object.entries(row)) {
    if (isMeta(k)) continue;

    if (!v || !String(v).trim()) continue;
    const text = String(v).trim();
    if (k.startsWith('Bagnetchon Signature Menu') || k.startsWith('The Grand Truffle Series')) {
      // Multi-select column: comma-separated selections (lechon sizes, or the
      // truffle series checkbox group).
      for (const part of text.split(/,\s+/).map((s) => s.trim()).filter(Boolean)) {
        selected_items.push({ sheet_column_header: k, selected_text: part });
      }
    } else {
      selected_items.push({ sheet_column_header: k, selected_text: text });
    }
  }

  const serviceMethod = String(row['Service Method '] ?? row['Service Method'] ?? '').trim();
  const deliveryLocationKey = Object.keys(row).find((k) => String(k).toLowerCase().trim().startsWith('delivery location'));
  const deliveryLocation = deliveryLocationKey ? String(row[deliveryLocationKey] ?? '').trim() : '';

  return { json: {
    source: 'google_sheet',
    source_row_id: 'gs:' + idHash,
    customer: {
      email,
      name: String(row['What is your name?'] ?? '').trim(),
      phone: String(row['Contact number or mobile (for confirmation & follow-up)'] ?? '').trim(),
    },
    fulfillment: {
      date: String(row['What date, day and time do you need the food/service?'] ?? '').trim(),
      type: serviceMethod,
      address: deliveryLocation || null,
      event_type: String(row['What type of event are you planning?'] ?? '').trim(),
      guest_count: row['Estimated number of guests attending:'] ?? null,
    },
    selected_items,
    writeback: {
      kind: 'google_sheet',
      spreadsheet_id: $vars.GS_SPREADSHEET_ID,
      sheet_name: $vars.GS_RESPONSES_SHEET,
      row_number: row.row_number ?? null,
    },
  }};
});

// Ping Slack for EVERY order that has an invoice — newly created OR already
// existing (idempotent re-run). The only thing filtered out is rows that
// produced no invoice at all (those go to the failure path). Enrich each ping
// with the full order detail by matching the summary back to its normalized
// order (source_row_id).
const orders = $('Normalize Order').all().map((i) => i.json);
const byId = new Map(orders.map((o) => [o.source_row_id, o]));

return $input.all()
  .map((e) => e.json)
  .filter((s) => s && s.ok === true && s.invoice_id)
  .map((s) => {
    const o = byId.get(s.source_row_id) || {};
    const c = o.customer || {};
    const f = o.fulfillment || {};
    const items = (o.selected_items || []).map((x) => x.selected_text).filter(Boolean);
    const isPickup = /pick.?up/i.test(String(f.type || ''));
    const existed = s.idempotent === true;

    const fields = {};
    fields.invoice = (s.invoice_number || s.invoice_id) + (existed ? ' (already invoiced)' : '');
    fields.customer = s.customer_name || c.name || '(unknown)';
    if (c.phone) fields.phone = c.phone;
    if (c.email) fields.email = c.email;
    if (f.type) fields.service = f.type;
    if (f.date) fields.date = f.date;
    if (f.address && !isPickup) fields.location = f.address;
    if (f.event_type || f.guest_count) {
      fields.event = (f.event_type || '') + (f.guest_count ? ' (' + f.guest_count + ' guests)' : '');
    }
    if (items.length) fields.items = items.join(', ');
    fields.total = (s.total != null) ? ((s.currency ? s.currency + ' ' : '') + s.total) : '(n/a)';

    return { json: {
      severity: 'info',
      stage: existed ? 'invoice-exists' : 'invoice-created',
      source: s.source || 'google_sheet',
      fields,
      review: Array.isArray(s.review_flags) ? s.review_flags : [],
    } };
  });

// Build a notify payload for EACH failed row.
return $input.all().map((entry) => {
  const v = entry.json;
  return { json: {
    severity: 'error',
    stage: 'sheet-intake-validation',
    source: 'google_sheet',
    errors: v.errors || ['unknown validation failure'],
    row: v.row,
  }};
});

// Ping Slack for any order that FAILED to produce an invoice — so no order is
// silently missed. Catches soft failures (sub returned ok:false) AND hard sub
// crashes (Call: Order → Invoice runs with continueOnFail, so a thrown error
// arrives here as an item carrying `error`). Idempotent skips and successes are
// NOT failures and are filtered out. Enrich with order detail for manual handling.
const orders = $('Normalize Order').all().map((i) => i.json);
const byId = new Map(orders.map((o) => [o.source_row_id, o]));

return $input.all()
  .map((e) => e.json)
  .filter((s) => {
    if (!s) return false;
    if (s.error) return true;            // hard crash item (continueOnFail)
    if (s.ok === true) return false;     // success or idempotent skip
    return true;                         // ok:false → real failure
  })
  .map((s) => {
    const o = byId.get(s.source_row_id) || {};
    const c = o.customer || {};
    const f = o.fulfillment || {};
    const items = (o.selected_items || []).map((x) => x.selected_text).filter(Boolean);
    const isPickup = /pick.?up/i.test(String(f.type || ''));

    const fields = {};
    fields.customer = s.customer_name || c.name || '(unknown)';
    if (c.phone) fields.phone = c.phone;
    if (c.email) fields.email = c.email;
    if (f.type) fields.service = f.type;
    if (f.date) fields.date = f.date;
    if (f.address && !isPickup) fields.location = f.address;
    if (f.event_type || f.guest_count) {
      fields.event = (f.event_type || '') + (f.guest_count ? ' (' + f.guest_count + ' guests)' : '');
    }
    if (items.length) fields.items = items.join(', ');

    const reason = (s.error && (s.error.message || s.error)) || s.message || 'invoice not created';

    return { json: {
      severity: 'error',
      stage: 'invoice-failed',
      source: s.source || 'google_sheet',
      errors: [String(reason)],
      fields,
    } };
  });
